class Solution {
    string s;
    int len;
    vector<vector<vector<int>>> memo;

    int dfs(int pos, int tight, int hasDiff) {
        if (pos == len) {
            return hasDiff;
        }
        if (memo[pos][tight][hasDiff] != -1) {
            return memo[pos][tight][hasDiff];
        }

        int max_digit = tight ? (s[pos] - '0') : 9;
        int total = 0;
        for (int d = 0; d <= max_digit; d++) {
            if (d == 3 || d == 4 || d == 7) continue;
            int next_tight = tight && (d == max_digit);
            int next_hasDiff = hasDiff || (d == 2 || d == 5 || d == 6 || d == 9);
            total += dfs(pos + 1, next_tight, next_hasDiff);
        }

        return memo[pos][tight][hasDiff] = total;
    }
public:
    int rotatedDigits(int n) {
        s = to_string(n);
        len = s.size();
        memo.assign(len, vector<vector<int>>(2, vector<int>(2, -1)));
        return dfs(0, 1, 0);
    }
};
